319:
SELECT COUNT(DISTINCT c."atom_id") AS element_count
FROM "connected" c
WHERE c."bond_id" = 'TR001_3_4';

416:
SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (
            WHERE c."language" = 'French'
        ) / NULLIF(COUNT(*), 0)::NUMERIC,
        2
    ) AS percentage
FROM "foreign_data" c
WHERE c."power" IS NULL OR c."power" = '*';

714:
SELECT c."text"
FROM "comments" c
WHERE c."userdisplayname" LIKE '%Harvey Motulsky%';

588:
SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

572:
SELECT p."viewcount"
FROM "posts" p
WHERE p."title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

745:
SELECT p."id"
FROM "publisher" p
WHERE p."publisher_name" LIKE '%Star Trek%';

803:
SELECT sp."id"
FROM "superpower" AS sp
WHERE LOWER(sp."power_name") = LOWER('cryokinesis');

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(DISTINCT m."member_id") AS president_count
FROM "member" m
WHERE LOWER(m."position") LIKE '%president%';
